{
  "category_edits": [
    {
      "category": "architecture_interaction",
      "rationale": "Across all four datasets, add a jointly trained residual GELU feed-forward block of width 128 before the unchanged causal pooling. Xavier-initialize W1 and zero-initialize W2 so the block initially preserves GRU outputs. Retain the GRU backbone, embeddings, readout, scoring, loss, optimizer and training settings.",
      "edits": [
        {
          "find": "            self.item_emb.weight[0].zero_()\n\n    def _interest_states",
          "replace": "            self.item_emb.weight[0].zero_()\n        self.residual_ffn_in = nn.Linear(hidden_units, 128)\n        self.residual_ffn_out = nn.Linear(128, hidden_units)\n        nn.init.xavier_uniform_(self.residual_ffn_in.weight)\n        nn.init.zeros_(self.residual_ffn_in.bias)\n        nn.init.zeros_(self.residual_ffn_out.weight)\n        nn.init.zeros_(self.residual_ffn_out.bias)\n\n    def _interest_states"
        },
        {
          "find": "        out, _ = self.gru(emb)\n        positions = torch.arange(seq.size(1), device=seq.device)",
          "replace": "        out, _ = self.gru(emb)\n        out = out + self.residual_ffn_out(\n            torch.nn.functional.gelu(self.residual_ffn_in(out))\n        )\n        positions = torch.arange(seq.size(1), device=seq.device)"
        },
        {
          "find": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n",
          "replace": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n            \"architecture\": \"gru_residual_gelu_ffn_128\",\n"
        },
        {
          "find": "        model = ModelClass(\n            itemnum=meta[\"itemnum\"],",
          "replace": "        if meta.get(\"architecture\") != \"gru_residual_gelu_ffn_128\":\n            raise RuntimeError(f\"Incompatible GRU residual architecture for {ds}\")\n        model = ModelClass(\n            itemnum=meta[\"itemnum\"],"
        }
      ]
    }
  ],
  "change_summary": "Add an identity-initialized residual feed-forward block before GRU causal pooling, with matching checkpoint metadata and embedded predictor validation. Preserve one model per category and all existing training settings."
}
